import{_ as a,c as t,o as r,ae as s}from"./chunks/framework.DNEoaTf_.js";const b=JSON.parse('{"title":"Frequently Asked Questions (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"en/faq.md","filePath":"en/faq.md"}'),i={name:"en/faq.md"};function o(n,e,l,h,u,d){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="frequently-asked-questions-faq" tabindex="-1">Frequently Asked Questions (FAQ) <a class="header-anchor" href="#frequently-asked-questions-faq" aria-label="Permalink to &quot;Frequently Asked Questions (FAQ)&quot;">​</a></h1><h2 id="general-questions" tabindex="-1">General Questions <a class="header-anchor" href="#general-questions" aria-label="Permalink to &quot;General Questions&quot;">​</a></h2><h3 id="q-is-this-extension-free" tabindex="-1">Q: Is this extension free? <a class="header-anchor" href="#q-is-this-extension-free" aria-label="Permalink to &quot;Q: Is this extension free?&quot;">​</a></h3><p>Yes, it&#39;s completely free. It&#39;s published as an open-source project.</p><h3 id="q-which-browsers-are-supported" tabindex="-1">Q: Which browsers are supported? <a class="header-anchor" href="#q-which-browsers-are-supported" aria-label="Permalink to &quot;Q: Which browsers are supported?&quot;">​</a></h3><p>The following browsers are supported:</p><ul><li>Google Chrome</li><li>Microsoft Edge</li><li>Brave</li><li>Firefox (planned)</li><li>Other Chromium-based browsers</li></ul><h3 id="q-where-is-data-stored" tabindex="-1">Q: Where is data stored? <a class="header-anchor" href="#q-where-is-data-stored" aria-label="Permalink to &quot;Q: Where is data stored?&quot;">​</a></h3><p>Video IDs and settings are stored in your browser&#39;s local storage (<code>chrome.storage.local</code>). Nothing is sent to external servers.</p><h3 id="q-can-i-use-it-offline" tabindex="-1">Q: Can I use it offline? <a class="header-anchor" href="#q-can-i-use-it-offline" aria-label="Permalink to &quot;Q: Can I use it offline?&quot;">​</a></h3><p>No, an internet connection is required as thumbnail information is fetched in real-time from YouTube&#39;s API. However, your settings are stored locally and will be preserved offline.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="q-what-thumbnail-sizes-can-i-download" tabindex="-1">Q: What thumbnail sizes can I download? <a class="header-anchor" href="#q-what-thumbnail-sizes-can-i-download" aria-label="Permalink to &quot;Q: What thumbnail sizes can I download?&quot;">​</a></h3><p>The following resolutions are available (varies by video):</p><ul><li>maxresdefault (1280x720 or 1920x1080)</li><li>sddefault (640x480)</li><li>hqdefault (480x360)</li><li>mqdefault (320x180)</li><li>default (120x90)</li></ul><h3 id="q-can-i-get-webp-format-thumbnails" tabindex="-1">Q: Can I get WebP format thumbnails? <a class="header-anchor" href="#q-can-i-get-webp-format-thumbnails" aria-label="Permalink to &quot;Q: Can I get WebP format thumbnails?&quot;">​</a></h3><p>Yes, if YouTube provides them, you can get thumbnails in both JPG and WebP formats.</p><h3 id="q-does-it-support-youtube-shorts" tabindex="-1">Q: Does it support YouTube Shorts? <a class="header-anchor" href="#q-does-it-support-youtube-shorts" aria-label="Permalink to &quot;Q: Does it support YouTube Shorts?&quot;">​</a></h3><p>Yes, it does. You can get thumbnails for Shorts using the same method as regular videos.</p><h3 id="q-can-i-use-it-on-playlists-or-search-results-pages" tabindex="-1">Q: Can I use it on playlists or search results pages? <a class="header-anchor" href="#q-can-i-use-it-on-playlists-or-search-results-pages" aria-label="Permalink to &quot;Q: Can I use it on playlists or search results pages?&quot;">​</a></h3><p>No, this extension only works on individual video playback pages.</p><h2 id="privacy-security" tabindex="-1">Privacy &amp; Security <a class="header-anchor" href="#privacy-security" aria-label="Permalink to &quot;Privacy &amp; Security&quot;">​</a></h2><h3 id="q-are-youtube-login-credentials-stored" tabindex="-1">Q: Are YouTube login credentials stored? <a class="header-anchor" href="#q-are-youtube-login-credentials-stored" aria-label="Permalink to &quot;Q: Are YouTube login credentials stored?&quot;">​</a></h3><p>No, login credentials are never stored. The extension uses YouTube&#39;s public API to fetch thumbnail information.</p><h3 id="q-is-data-shared-with-third-parties" tabindex="-1">Q: Is data shared with third parties? <a class="header-anchor" href="#q-is-data-shared-with-third-parties" aria-label="Permalink to &quot;Q: Is data shared with third parties?&quot;">​</a></h3><p>No, it&#39;s never shared. Thumbnails are fetched directly from YouTube and displayed in your browser.</p><h3 id="q-is-usage-data-collected" tabindex="-1">Q: Is usage data collected? <a class="header-anchor" href="#q-is-usage-data-collected" aria-label="Permalink to &quot;Q: Is usage data collected?&quot;">​</a></h3><p>No, there&#39;s no analytics or tracking implemented.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="q-some-thumbnails-aren-t-showing" tabindex="-1">Q: Some thumbnails aren&#39;t showing? <a class="header-anchor" href="#q-some-thumbnails-aren-t-showing" aria-label="Permalink to &quot;Q: Some thumbnails aren&#39;t showing?&quot;">​</a></h3><p>maxresdefault (maximum quality) is not available for all videos. If YouTube hasn&#39;t generated high-resolution thumbnails, only lower resolution thumbnails will be displayed.</p><h3 id="q-the-extension-isn-t-working" tabindex="-1">Q: The extension isn&#39;t working <a class="header-anchor" href="#q-the-extension-isn-t-working" aria-label="Permalink to &quot;Q: The extension isn&#39;t working&quot;">​</a></h3><ol><li>Verify you&#39;re on a YouTube video playback page</li><li>Try restarting your browser</li><li>Try disabling and re-enabling the extension</li><li>If still not resolved, report it on <a href="https://github.com/mosunset/youtube_watch_thumbnails/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li></ol><h2 id="development-contributing" tabindex="-1">Development &amp; Contributing <a class="header-anchor" href="#development-contributing" aria-label="Permalink to &quot;Development &amp; Contributing&quot;">​</a></h2><h3 id="q-is-it-open-source" tabindex="-1">Q: Is it open source? <a class="header-anchor" href="#q-is-it-open-source" aria-label="Permalink to &quot;Q: Is it open source?&quot;">​</a></h3><p>Yes, it&#39;s published under the MIT License. Visit the <a href="https://github.com/mosunset/youtube_watch_thumbnails" target="_blank" rel="noreferrer">GitHub repository</a>.</p><h3 id="q-where-can-i-request-features-or-report-bugs" tabindex="-1">Q: Where can I request features or report bugs? <a class="header-anchor" href="#q-where-can-i-request-features-or-report-bugs" aria-label="Permalink to &quot;Q: Where can I request features or report bugs?&quot;">​</a></h3><p>We accept them on <a href="https://github.com/mosunset/youtube_watch_thumbnails/issues" target="_blank" rel="noreferrer">GitHub Issues</a>.</p><h3 id="q-can-i-contribute-to-development" tabindex="-1">Q: Can I contribute to development? <a class="header-anchor" href="#q-can-i-contribute-to-development" aria-label="Permalink to &quot;Q: Can I contribute to development?&quot;">​</a></h3><p>Absolutely! Pull requests are welcome. Visit the <a href="https://github.com/mosunset/youtube_watch_thumbnails" target="_blank" rel="noreferrer">GitHub repository</a>.</p><h3 id="q-what-s-the-tech-stack" tabindex="-1">Q: What&#39;s the tech stack? <a class="header-anchor" href="#q-what-s-the-tech-stack" aria-label="Permalink to &quot;Q: What&#39;s the tech stack?&quot;">​</a></h3><ul><li>WXT (Framework)</li><li>React</li><li>TypeScript</li><li>Tailwind CSS</li></ul><div class="tip custom-block"><p class="custom-block-title">Have more questions?</p><p>If you can&#39;t find answers here, feel free to ask on <a href="https://github.com/mosunset/youtube_watch_thumbnails/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a>.</p></div>',43)])])}const p=a(i,[["render",o]]);export{b as __pageData,p as default};
